const rows = items.map((item) => item.json);

function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function norm(value) {
  return String(value || '').toLowerCase();
}

const total = rows.length;
const pendientes = rows.filter((r) => norm(r.estado).includes('pendiente')).length;
const proceso = rows.filter((r) => norm(r.estado).includes('proceso')).length;
const terminados = rows.filter((r) => norm(r.estado).includes('terminado') || norm(r.estado).includes('resuelto')).length;
const altas = rows.filter((r) => norm(r.prioridad) === 'alta').length;

const reportDate = new Date().toLocaleString('es-GT', { dateStyle: 'medium', timeStyle: 'short' });
const reportRowsJson = JSON.stringify(rows).replace(/</g, '\\u003c');

const tableRows = rows.map((row) => {
  const estado = row.estado || 'Sin estado';
  const estadoKey = norm(estado).includes('pendiente') ? 'pendiente'
    : norm(estado).includes('proceso') ? 'proceso'
    : (norm(estado).includes('terminado') || norm(estado).includes('resuelto')) ? 'terminado'
    : norm(estado).includes('rechazado') ? 'rechazado'
    : 'sinestado';
  const prioridad = row.prioridad || 'Baja';
  const prioridadKey = norm(prioridad) === 'alta' ? 'alta' : norm(prioridad) === 'media' ? 'media' : 'baja';
  const tecnicoOptions = [1, 2, 3, 4].map((num) => `<option value="Tecnico ${num}">Tecnico ${num}</option>`).join('');
  const technicianControl = estadoKey === 'terminado'
    ? `<span class="technician-label" data-tech-label="${esc(row.id)}">Sin asignar</span>`
    : `<select class="tech-select" data-tech-select="${esc(row.id)}" onchange="saveTechnician('${esc(row.id)}', this.value)">${tecnicoOptions}</select>`;
  const actionButtons = estadoKey === 'pendiente'
    ? `<button type="button" class="btn primary" onclick="takeTicket('${esc(row.id)}')">Pasar a proceso</button>`
    : estadoKey === 'proceso'
      ? `<button type="button" class="btn primary" onclick="openModal('${esc(row.id)}')">Cerrar ticket</button>`
      : estadoKey === 'terminado'
        ? `<span class="muted">Cerrado</span>`
        : `<span class="muted">No disponible</span>`;

  return `<tr data-status="${estadoKey}" data-priority="${prioridadKey}" data-search="${esc(`${row.id} ${row.nombre} ${row.correo} ${row.problema} ${estado} ${prioridad}`).toLowerCase()}">
    <td class="mono">#${esc(row.id)}</td>
    <td>
      <strong>${esc(row.nombre)}</strong>
      <span>${esc(row.correo)}</span>
    </td>
    <td class="issue">${esc(row.problema)}</td>
    <td><span class="pill priority ${prioridadKey}">${esc(prioridad)}</span></td>
    <td><span class="pill status ${estadoKey}">${esc(estado)}</span></td>
    <td>${esc(row.fecha || '')}</td>
    <td>${technicianControl}</td>
    <td class="solution">${esc(row.solucion || '')}</td>
    <td class="actions">
      ${actionButtons}
      <button type="button" class="btn" onclick="printTicket('${esc(row.id)}')">Reporte PDF</button>
    </td>
  </tr>`;
}).join('');

let html = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Help Desk - Dashboard</title>
  <style>
    :root {
      --bg: #f4f7fb;
      --panel: #ffffff;
      --line: #d8e0ea;
      --text: #172033;
      --muted: #667085;
      --brand: #0f766e;
      --brand-dark: #115e59;
      --danger: #b42318;
      --warn: #b54708;
      --ok: #067647;
      --info: #175cd3;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      background: var(--bg);
      color: var(--text);
      font-family: "Segoe UI", Arial, sans-serif;
      font-size: 14px;
    }
    header {
      background: #ffffff;
      border-bottom: 1px solid var(--line);
      padding: 22px 28px;
    }
    .topbar, main { max-width: 1320px; margin: 0 auto; }
    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
    }
    h1 { margin: 0; font-size: 24px; font-weight: 700; letter-spacing: 0; }
    .subtitle { margin: 5px 0 0; color: var(--muted); }
    main { padding: 24px 28px 40px; }
    .toolbar {
      display: grid;
      grid-template-columns: 1fr auto auto auto;
      gap: 10px;
      align-items: center;
      margin-bottom: 18px;
    }
    input, select, textarea {
      border: 1px solid var(--line);
      border-radius: 6px;
      padding: 10px 12px;
      font: inherit;
      background: #fff;
      color: var(--text);
    }
    .tech-select { min-width: 118px; padding: 8px 10px; }
    .technician-label { color: var(--muted); font-weight: 700; }
    .btn {
      border: 0;
      border-radius: 6px;
      padding: 10px 14px;
      font-weight: 700;
      cursor: pointer;
      background: #e6edf5;
      color: var(--text);
      white-space: nowrap;
    }
    .btn.primary { background: var(--brand); color: #fff; }
    .btn.primary:hover { background: var(--brand-dark); }
    .btn:disabled { opacity: .55; cursor: not-allowed; }
    .metrics {
      display: grid;
      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 12px;
      margin-bottom: 18px;
    }
    .metric {
      background: var(--panel);
      border: 1px solid var(--line);
      border-radius: 8px;
      padding: 14px;
    }
    .metric span { display: block; color: var(--muted); font-size: 12px; text-transform: uppercase; font-weight: 700; }
    .metric strong { display: block; margin-top: 6px; font-size: 26px; }
    .table-wrap {
      overflow: auto;
      background: var(--panel);
      border: 1px solid var(--line);
      border-radius: 8px;
    }
    table { width: 100%; border-collapse: collapse; min-width: 1220px; }
    th, td { padding: 12px 14px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; }
    th { background: #eef3f8; font-size: 12px; color: #344054; text-transform: uppercase; }
    tr:hover td { background: #f8fafc; }
    td strong, td span { display: block; }
    .mono { font-family: Consolas, monospace; font-weight: 700; }
    .issue { max-width: 330px; line-height: 1.35; }
    .solution { max-width: 250px; color: var(--muted); }
    .actions { min-width: 220px; }
    .actions .btn { margin: 0 6px 6px 0; }
    .muted { color: var(--muted); font-size: 12px; }
    .pill {
      display: inline-block;
      border-radius: 999px;
      padding: 5px 9px;
      font-size: 12px;
      font-weight: 800;
      line-height: 1;
      white-space: nowrap;
    }
    .priority.alta { background: #fee4e2; color: var(--danger); }
    .priority.media { background: #fef0c7; color: var(--warn); }
    .priority.baja { background: #dcfae6; color: var(--ok); }
    .status.pendiente { background: #e4e7ec; color: #344054; }
    .status.proceso { background: #d1e9ff; color: var(--info); }
    .status.terminado { background: #dcfae6; color: var(--ok); }
    .status.rechazado { background: #fee4e2; color: var(--danger); }
    .status.sinestado { background: #f2f4f7; color: #475467; }
    .modal {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(16, 24, 40, .62);
      align-items: center;
      justify-content: center;
      padding: 20px;
    }
    .modal.open { display: flex; }
    .modal-content {
      width: min(520px, 100%);
      background: #fff;
      border-radius: 8px;
      padding: 22px;
      box-shadow: 0 20px 45px rgba(16, 24, 40, .25);
    }
    .modal-content h2 { margin: 0 0 8px; font-size: 20px; }
    textarea { width: 100%; min-height: 130px; resize: vertical; margin: 10px 0; }
    .modal-actions { display: flex; justify-content: flex-end; gap: 10px; }
    .report-only { display: none; }

    .print-report { display: none; }
    @media print {
      body { background: #fff; }
      body > header, body > main, .modal { display: none !important; }
      .print-report.ready {
        display: block;
        color: #172033;
        font-family: "Segoe UI", Arial, sans-serif;
        margin: 22px;
        line-height: 1.45;
      }
      .report-header { border-bottom: 3px solid #0f766e; padding-bottom: 14px; margin-bottom: 22px; }
      .report-header h1 { font-size: 24px; margin: 0 0 6px; }
      .report-meta { color: #667085; font-size: 12px; }
      .report-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 16px 0; }
      .report-box { border: 1px solid #d8e0ea; border-radius: 6px; padding: 12px; }
      .report-label { display: block; color: #667085; font-size: 11px; text-transform: uppercase; font-weight: 800; margin-bottom: 4px; }
      .report-title { font-size: 16px; margin: 22px 0 8px; color: #115e59; }
      .report-block { border: 1px solid #d8e0ea; border-radius: 6px; padding: 14px; min-height: 80px; white-space: pre-wrap; }
      .report-footer { margin-top: 40px; display: grid; grid-template-columns: 1fr 1fr; gap: 50px; }
      .report-sign { border-top: 1px solid #667085; padding-top: 8px; text-align: center; color: #667085; }
    }
    @media (max-width: 900px) {
      .topbar, .toolbar { grid-template-columns: 1fr; display: grid; }
      .metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }
  </style>
</head>
<body>
  <header>
    <div class="topbar">
      <div>
        <h1>Dashboard Help Desk</h1>
        <p class="subtitle">Gestion de tickets, prioridad, asignacion visual y cierre tecnico</p>
      </div>
      <button class="btn primary" onclick="location.reload()">Actualizar</button>
    </div>
  </header>
  <main>
    <section class="report-only">
      <h2>Reporte tecnico de tickets</h2>
      <p>Generado: ${esc(reportDate)}</p>
    </section>
    <section class="metrics">
      <div class="metric"><span>Total</span><strong>${total}</strong></div>
      <div class="metric"><span>Pendientes</span><strong>${pendientes}</strong></div>
      <div class="metric"><span>En proceso</span><strong>${proceso}</strong></div>
      <div class="metric"><span>Terminados</span><strong>${terminados}</strong></div>
      <div class="metric"><span>Alta prioridad</span><strong>${altas}</strong></div>
    </section>
    <section class="toolbar">
      <input id="search" placeholder="Buscar por ID, usuario, correo o problema" oninput="filterRows()">
      <select id="statusFilter" onchange="filterRows()">
        <option value="">Todos los estados</option>
        <option value="pendiente">Pendiente</option>
        <option value="proceso">En proceso</option>
        <option value="terminado">Terminado</option>
        <option value="rechazado">Rechazado</option>
      </select>
      <select id="priorityFilter" onchange="filterRows()">
        <option value="">Todas las prioridades</option>
        <option value="alta">Alta</option>
        <option value="media">Media</option>
        <option value="baja">Baja</option>
      </select>
      <button class="btn" onclick="resetFilters()">Limpiar</button>
    </section>
    <section class="table-wrap">
      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Solicitante</th>
            <th>Problema</th>
            <th>Prioridad</th>
            <th>Estado</th>
            <th>Fecha</th>
            <th>Tecnico</th>
            <th>Solucion</th>
            <th class="actions">Accion</th>
          </tr>
        </thead>
        <tbody id="ticketRows">${tableRows || '<tr><td colspan="9">No hay tickets registrados.</td></tr>'}</tbody>
      </table>
    </section>
  </main>

  <div id="modal" class="modal" role="dialog" aria-modal="true">
    <div class="modal-content">
      <h2>Cerrar ticket</h2>
      <p id="ticketLabel" class="muted"></p>
      <textarea id="solucion" placeholder="Describe la causa, acciones realizadas y resultado final"></textarea>
      <div class="modal-actions">
        <button class="btn" onclick="closeModal()">Cancelar</button>
        <button class="btn primary" onclick="sendResolution()">Guardar solucion</button>
      </div>
    </div>
  </div>

  <section id="printReport" class="print-report" aria-hidden="true"></section>

  <script>
    let currentTicket = null;
    const ticketsForReport = ${reportRowsJson};
    const technicianKey = 'helpdeskTechnicians';

    function webhookBase() {
      return '/webhook/';
    }

    function loadTechnicians() {
      try {
        return JSON.parse(localStorage.getItem(technicianKey) || '{}');
      } catch (error) {
        return {};
      }
    }

    function getTechnician(id) {
      return loadTechnicians()[id] || 'Tecnico 1';
    }

    function saveTechnician(id, value) {
      const technicians = loadTechnicians();
      technicians[id] = value || 'Tecnico 1';
      localStorage.setItem(technicianKey, JSON.stringify(technicians));
      applyTechnicians();
    }

    function applyTechnicians() {
      const technicians = loadTechnicians();
      document.querySelectorAll('[data-tech-select]').forEach((select) => {
        const id = select.dataset.techSelect;
        select.value = technicians[id] || select.value || 'Tecnico 1';
      });
      document.querySelectorAll('[data-tech-label]').forEach((label) => {
        const id = label.dataset.techLabel;
        label.textContent = technicians[id] || 'Sin asignar';
      });
    }

    function openModal(id) {
      currentTicket = id;
      document.getElementById('ticketLabel').textContent = 'Ticket #' + id + ' - ' + getTechnician(id);
      document.getElementById('solucion').value = '';
      document.getElementById('modal').classList.add('open');
      document.getElementById('solucion').focus();
    }

    function closeModal() {
      document.getElementById('modal').classList.remove('open');
    }

    function filterRows() {
      const search = document.getElementById('search').value.trim().toLowerCase();
      const status = document.getElementById('statusFilter').value;
      const priority = document.getElementById('priorityFilter').value;

      document.querySelectorAll('#ticketRows tr').forEach((row) => {
        const matchesSearch = !search || row.dataset.search.includes(search);
        const matchesStatus = !status || row.dataset.status === status;
        const matchesPriority = !priority || row.dataset.priority === priority;
        row.style.display = matchesSearch && matchesStatus && matchesPriority ? '' : 'none';
      });
    }

    function resetFilters() {
      document.getElementById('search').value = '';
      document.getElementById('statusFilter').value = '';
      document.getElementById('priorityFilter').value = '';
      filterRows();
    }

    async function takeTicket(id) {
      const technician = getTechnician(id);
      const response = await fetch(webhookBase() + 'tomar-ticket?id=' + encodeURIComponent(id), { method: 'GET' });
      if (!response.ok) {
        alert('No se pudo pasar el ticket a En proceso. Verifica que el workflow de procesamiento este activo.');
        return;
      }
      saveTechnician(id, technician);
      location.reload();
    }

    async function sendResolution() {
      const solucion = document.getElementById('solucion').value.trim();
      if (solucion.length < 10) {
        alert('Escribe una descripcion de al menos 10 caracteres.');
        return;
      }

      const url = webhookBase() + 'cerrar-ticket?id=' + encodeURIComponent(currentTicket) + '&solucion=' + encodeURIComponent(solucion);
      const response = await fetch(url, { method: 'GET' });
      if (!response.ok) {
        alert('No se pudo actualizar el ticket.');
        return;
      }
      closeModal();
      location.reload();
    }

    function safe(value) {
      return String(value || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
    }

    function formatDate(value) {
      return value ? safe(value) : 'No registrado';
    }

    function printTicket(id) {
      const ticket = ticketsForReport.find((item) => String(item.id) === String(id));
      if (!ticket) {
        alert('No se encontro el ticket seleccionado.');
        return;
      }

      const technician = getTechnician(id);
      const generatedAt = new Date().toLocaleString('es-GT', { dateStyle: 'medium', timeStyle: 'short' });
      const report = document.getElementById('printReport');
      if (!report) {
        alert('No se encontro el contenedor del reporte. Actualiza el dashboard e intenta de nuevo.');
        return;
      }

      report.innerHTML =
        '<div class="report-header"><h1>Reporte tecnico de ticket #' + safe(ticket.id) + '</h1><div class="report-meta">Generado: ' + safe(generatedAt) + '</div></div>' +
        '<section class="report-grid">' +
        '<div class="report-box"><span class="report-label">Solicitante</span><strong>' + safe(ticket.nombre) + '</strong><br>' + safe(ticket.correo) + '</div>' +
        '<div class="report-box"><span class="report-label">Estado</span><strong>' + safe(ticket.estado || 'Sin estado') + '</strong></div>' +
        '<div class="report-box"><span class="report-label">Tecnico asignado</span><strong>' + safe(technician) + '</strong></div>' +
        '<div class="report-box"><span class="report-label">Prioridad</span><strong>' + safe(ticket.prioridad || 'Baja') + '</strong></div>' +
        '<div class="report-box"><span class="report-label">Fecha de apertura</span>' + formatDate(ticket.fecha) + '</div>' +
        '<div class="report-box"><span class="report-label">Fecha de cierre</span>' + formatDate(ticket.fecha_resolucion) + '</div>' +
        '</section>' +
        '<h2 class="report-title">Problema reportado</h2><div class="report-block">' + safe(ticket.problema || 'Sin descripcion') + '</div>' +
        '<h2 class="report-title">Solucion tecnica aplicada</h2><div class="report-block">' + safe(ticket.solucion || 'Pendiente de documentar') + '</div>' +
        '<h2 class="report-title">Observaciones</h2><div class="report-block">Validar con el usuario que el servicio funciona correctamente y documentar cualquier seguimiento requerido.</div>' +
        '<section class="report-footer"><div class="report-sign">Tecnico responsable</div><div class="report-sign">Vo. Bo. / Revision</div></section>';

      report.classList.add('ready');
      report.setAttribute('aria-hidden', 'false');
      setTimeout(() => window.print(), 100);
    }

    window.addEventListener('afterprint', () => {
      const report = document.getElementById('printReport');
      if (report) {
        report.classList.remove('ready');
        report.setAttribute('aria-hidden', 'true');
      }
    });

    window.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') closeModal();
    });

    applyTechnicians();
  </script>
</body>
</html>`;

return [{ json: { html } }];
